
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_zvpbeloc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_zvpbeloc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.668228702254667e-02, -7.560176092770222e-02, -7.404111431794082e-02, -7.178146514607742e-02, -6.849604829730062e-02, -6.368495572191923e-02, -5.655579829279305e-02, -4.582240323876304e-02, -2.977587285805901e-02, -1.062099015560523e-02, -2.332205798478174e-03, -3.546288830807089e-02, -4.735826886551724e-02, -2.913267270525170e-02, -7.858326117875980e-03, -4.156762760190267e-04, -1.774357495762924e-06, -4.519621581815084e-11, -1.455647883662054e-24, -7.933341597492271e-35]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


